--
-- Name: users; Type: TABLE; Schema: public; Owner: sobi
--

CREATE TABLE public.users (
    id bigint NOT NULL,
    email character varying(255) NOT NULL,
    password character varying(255),
    name character varying(100) NOT NULL,
    role character varying(20),
    credit_rating character varying(3),
    provider character varying(10) NOT NULL,
    provider_id character varying(255),
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    deleted_at timestamp without time zone,
    updated_at timestamp without time zone,
    notification boolean DEFAULT true NOT NULL,
    user_key character varying(60) NOT NULL,
    birth_date date,
    CONSTRAINT chk_users_provider CHECK (((provider)::text = ANY ((ARRAY['LOCAL'::character varying, 'GOOGLE'::character varying])::text[]))),
    CONSTRAINT chk_users_role CHECK (((role)::text = ANY ((ARRAY['ENTREPRENEUR'::character varying, 'PREENTREPRENEUR'::character varying])::text[])))
);


ALTER TABLE public.users OWNER TO sobi;

--
-- Name: TABLE users; Type: COMMENT; Schema: public; Owner: sobi
--

COMMENT ON TABLE public.users IS '회원 (ERD: user)';


--
-- Name: COLUMN users.role; Type: COMMENT; Schema: public; Owner: sobi
--

COMMENT ON COLUMN public.users.role IS '창업자 / 예비 창업자 (ENTREPRENEUR / PREENTREPRENEUR)';


--
-- Name: COLUMN users.provider; Type: COMMENT; Schema: public; Owner: sobi
--

COMMENT ON COLUMN public.users.provider IS 'LOCAL / GOOGLE';


--
-- Name: COLUMN users.created_at; Type: COMMENT; Schema: public; Owner: sobi
--

COMMENT ON COLUMN public.users.created_at IS '가입날짜';


--
-- Name: COLUMN users.deleted_at; Type: COMMENT; Schema: public; Owner: sobi
--

COMMENT ON COLUMN public.users.deleted_at IS '탈퇴날짜';


--
-- Name: COLUMN users.updated_at; Type: COMMENT; Schema: public; Owner: sobi
--

COMMENT ON COLUMN public.users.updated_at IS '수정날짜';


--
-- Name: COLUMN users.notification; Type: COMMENT; Schema: public; Owner: sobi
--

COMMENT ON COLUMN public.users.notification IS '알람 동의 여부';


--
-- Name: COLUMN users.user_key; Type: COMMENT; Schema: public; Owner: sobi
--

COMMENT ON COLUMN public.users.user_key IS '싸피 금융망 user key';


--
-- Name: COLUMN users.birth_date; Type: COMMENT; Schema: public; Owner: sobi
--

COMMENT ON COLUMN public.users.birth_date IS '생년월일 (소셜 가입 시 null, 온보딩에서 입력)';


